package au.aumanet.app;
import java.util.concurrent.atomic.*;
/** Exact recovery method; Android cache/scan/permission delivery are declared boundaries. */
public final class NodeRecoveryScanTest {
 static int tests,checks;static void check(boolean b){checks++;if(!b)throw new AssertionError("Checked recovery scan regression");}
 static NodeRecoveryHarness fixture()throws Exception{RecoveryClock.now=200000;return new NodeRecoveryHarness(new NodeConnectionProfile(NodeConnectionProfileTest.profile()));}
 static NodeRecoveryScan.Result poll(NodeRecoveryHarness h,long lost){return h.recoveryStatus("owned",h.profile.digest,lost,()->h.allowed.get());}
 static void staleThenFresh()throws Exception{tests++;NodeRecoveryHarness h=fixture();h.wifi.results.add(new RecoveryResult(h.profile.ssid,"02:44:00:00:00:01",50000000));check(poll(h,100000)==NodeRecoveryScan.Result.WAITING);check(h.wifi.requests==1);check(poll(h,100000)==NodeRecoveryScan.Result.WAITING&&h.wifi.requests==1);RecoveryClock.now+=4000;h.wifi.results.clear();h.wifi.results.add(new RecoveryResult(h.profile.ssid,"02:44:00:00:00:01",RecoveryClock.now*1000));check(poll(h,100000)==NodeRecoveryScan.Result.READY);check(h.wifi.requests==1);}
 static void absentAndRateBound()throws Exception{tests++;NodeRecoveryHarness h=fixture();check(poll(h,100000)==NodeRecoveryScan.Result.WAITING&&h.wifi.requests==1);RecoveryClock.now+=59000;check(poll(h,100000)==NodeRecoveryScan.Result.WAITING&&h.wifi.requests==1);RecoveryClock.now+=3000;check(poll(h,100000)==NodeRecoveryScan.Result.WAITING&&h.wifi.requests==2);h.profile=new NodeConnectionProfile(NodeConnectionProfileTest.profile());RecoveryClock.now+=4000;check(poll(h,100000)==NodeRecoveryScan.Result.WAITING&&h.wifi.requests==2);}
 static void permissions()throws Exception{tests++;for(int kind=0;kind<3;kind++){NodeRecoveryHarness h=fixture();if(kind==0)h.context.permission=1;if(kind==1)h.location.enabled=false;if(kind==2)h.wifi.enabled=false;check(poll(h,100000)==NodeRecoveryScan.Result.UNAVAILABLE);check(h.wifi.requests==0);}}
 static void cancelAndReplacement()throws Exception{tests++;NodeRecoveryHarness h=fixture();h.wifi.afterRead=()->h.allowed.set(false);check(poll(h,100000)==NodeRecoveryScan.Result.UNAVAILABLE);check(h.wifi.requests==0);NodeRecoveryHarness changed=fixture();changed.wifi.afterRead=()->{try{changed.profile=new NodeConnectionProfile(NodeConnectionProfileTest.profile());}catch(Exception failed){throw new IllegalStateException();}};check(poll(changed,100000)==NodeRecoveryScan.Result.UNAVAILABLE);check(changed.wifi.requests==0);NodeRecoveryHarness replaced=fixture();replaced.attach("replacement");check(poll(replaced,100000)==NodeRecoveryScan.Result.UNAVAILABLE&&replaced.wifi.requests==0);}
 static void deniedScanIsNotAuthority()throws Exception{tests++;NodeRecoveryHarness h=fixture();h.wifi.accepted=false;check(poll(h,100000)==NodeRecoveryScan.Result.WAITING);check(h.wifi.requests==1);RecoveryClock.now+=4000;check(poll(h,100000)==NodeRecoveryScan.Result.WAITING);check(h.wifi.requests==1);h.wifi.results.add(new RecoveryResult("Other-node","02:44:00:00:00:01",RecoveryClock.now*1000));RecoveryClock.now+=4000;check(poll(h,100000)==NodeRecoveryScan.Result.WAITING);check(h.wifi.requests==1);}
 static void clock()throws Exception{tests++;NodeRecoveryScanBudget b=new NodeRecoveryScanBudget();check(!b.claim(-1));check(b.claim(100));check(!b.claim(100));check(!b.claim(99));check(!b.claim(60099));check(b.claim(60100));NodeRecoveryHarness h=fixture();check(poll(h,RecoveryClock.now+1)==NodeRecoveryScan.Result.UNAVAILABLE&&h.wifi.requests==0);}
 public static void main(String[] args)throws Exception{staleThenFresh();absentAndRateBound();permissions();cancelAndReplacement();deniedScanIsNotAuthority();clock();System.out.print("{\"status\":\"passed\",\"testCount\":"+tests+",\"assertionCount\":"+checks+"}");}
}
